"""Unit tests for wavcheck.wav_rms (WAVs are generated by the tests)."""

import array
import math
import os
import sys
import tempfile
import unittest
import wave

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import wavcheck  # noqa: E402


def _write_wav(path, samples, channels=2, sampwidth=2, rate=44100):
    with wave.open(path, "wb") as w:
        w.setnchannels(channels)
        w.setsampwidth(sampwidth)
        w.setframerate(rate)
        if sampwidth == 2:
            w.writeframes(array.array("h", samples).tobytes())
        else:
            w.writeframes(bytes(samples))


class WavRmsTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.path = os.path.join(self.tmp.name, "t.wav")

    def tearDown(self):
        self.tmp.cleanup()

    def test_silence_is_zero(self):
        _write_wav(self.path, [0] * (44100 * 2))
        self.assertEqual(wavcheck.wav_rms(self.path), 0.0)

    def test_full_scale_square(self):
        _write_wav(self.path, [1000 if (i // 50) % 2 else -1000 for i in range(8820)])
        self.assertAlmostEqual(wavcheck.wav_rms(self.path), 1000.0, places=3)

    def test_sine_rms(self):
        n = 44100
        _write_wav(self.path, [round(1000 * math.sin(2 * math.pi * 441 * i / n)) for i in range(n)],
                   channels=1)
        self.assertAlmostEqual(wavcheck.wav_rms(self.path), 707.1, delta=1.0)

    def test_8bit_rejected(self):
        _write_wav(self.path, [128] * 100, channels=1, sampwidth=1)
        with self.assertRaises(ValueError):
            wavcheck.wav_rms(self.path)


if __name__ == "__main__":
    unittest.main()
